mapper.select:
SELECT m.merchant_id, m.merchant_name, m.shop_name, m.shop_logo_url, m.description, m.contact_name, m.contact_phone, m.contact_email, m.status, m.create_time, m.update_time, creator.username as creator_name, updater.username as updater_name FROM merchant m LEFT JOIN user creator ON m.create_by = creator.id LEFT JOIN user updater ON m.update_by = updater.id WHERE m.is_deleted = 0
AND m.merchant_name LIKE CONCAT('%', #{condition.merchantName}, '%')
AND m.id = #{condition.id}
AND m.status = #{condition.status}
ORDER BY m.create_time DESC
